void test_private_ahb()
{
  unsigned int data = 1234, get_data = 0;
  uintptr_t addr = 0x08;

  ace_write_to_private_ahb(addr, data);
  ace_nbsync(0); // to ensure write finished
  get_data = ace_read_from_private_ahb(addr);
  if (data != get_data) {
    printf("%u\n", get_data);
    exit(1);
  }
}

void test_mem()
{
  unsigned int x = 123, y = 0;
  ace_run_with_mem((uintptr_t) &y, (uintptr_t) &x);
  ace_nbsync(0);
  if (x != y) {
    printf("%u vs %u\n", x, y);
    exit(1);
  }
}

void test_acp()
{
  for (size_t i = 1; i <= 4; i++) {
    ace_write_to_myacp(i);
    unsigned int cnt = ace_read_from_readcnt_acp();
    if (cnt != i) {
      printf("cnt: %u\n", cnt);
      exit(1);
    }
  }
}

static inline void flush_cache_line(void* addr)
{
  // Not all Andes has NDS_CM_SUPPORT, so this may not work well
  // if used, -march=zicbom
  asm volatile("cbo.flush %0" : : "r"(addr) : "memory");
}

void test_shared_axi()
{
  popo_axi64_t a = 12345;
  popo_axi64_t res = 0;
  unsigned int inc = 1;
  ace_add_on_axi((uintptr_t) &res, (uintptr_t) &a, inc);
  if (res != (a + 1)) {
    printf("Fail axi: %llu\n", res);
    exit(1);
  }
}

void test_reverse_sram()
{
  unsigned int sram_addr = 10;
  unsigned int sram_expected_data = 0x78563412;
  rvs_sram_t sram_data = 0x12345678;

  ace_reset_rvs_sram(sram_addr);

  ace_nbsync(reset_sram_insns);
  ace_wr_rvs_sram(sram_addr, sram_data);
  ace_reverse_sram(sram_addr);

  ace_nbsync(reverse_insns);
  sram_data = ace_rd_rvs_sram(sram_addr);
  if (sram_expected_data != sram_data) {
    exit(1);
  }
}

void test_reverse_acr()
{
  unsigned long long acr_expected_data = 0xddccbbaa78563412;
  rvs_acr_t acr_data = 0x12345678aabbccdd;

  acr_data = ace_reverse_acr(acr_data);
  if (acr_expected_data != acr_data) {
    exit(1);
  }
}

void test_reverse_xrf()
{
  unsigned long xrf_data = 0x12345678;
  unsigned long xrf_expected_data = 0x78563412;

  xrf_data = ace_reverse_xrf_32(xrf_data);
  if (xrf_expected_data != xrf_data) {
    printf("fail: %#lx vs %#lx\n", xrf_expected_data, xrf_data);
    exit(1);
  }
}

void test_add_200()
{
  unsigned long xrf_data = 0x78563412;
  acrw200_t add_data;
  acrw200_imp_t add_data_result, add_expected_data;
  add_data.dword0 = 0x3;
  add_data.dword1 = 0x0;
  add_data.dword2 = 0x0;
  add_data.msb_8 = 0x80;
  add_expected_data.dword0 = 0x78563415;
  add_expected_data.dword1 = 0x0;
  add_expected_data.dword2 = 0x0;
  add_expected_data.msb_8 = 0x80;

  ace_add_200(add_data, xrf_data);
  add_data_result = ace_rd_acrw200_imp(acrw200_imp_0);
  if (add_expected_data.dword0 != add_data_result.dword0) {
    printf("%llx  vs %llx\n", add_expected_data.dword0, add_data_result.dword0);
    exit(1);
  }
  if (add_expected_data.dword1 != add_data_result.dword1) {
    exit(1);
  }
  if (add_expected_data.dword2 != add_data_result.dword2) {
    exit(1);
  }
  if (add_expected_data.msb_8 != add_data_result.msb_8) {
    exit(1);
  }
}

void test_xrf_accumulate_vec()
{
  unsigned long long ret = 0;
  unsigned long long expected_ret = 0;
  unsigned long long a = 0x8323928;
  unsigned long long b = 0x1a2b3c4;

  for (int i = 0; i < 5; i++) {
    expected_ret += a + b;
  }

  acrw8_t cnt = 0xf5;
  ret = ace_vec_accumulate_xrf(a, b, cnt);
  if (expected_ret != ret) {
    exit(1);
  }
}

void test_accumulate_ent()
{
  for (unsigned int addr = 0; addr < 5; ++addr) {
    ace_reset_acc_sram(addr);
  }

  acc_sram_t data[] = {0x13579, 0x83239289, 0xab73f, 0x555339dd, 0x9654abc};

  for (unsigned int addr = 0; addr < 5; ++addr) {
    ace_wr_acc_sram(addr, data[addr]);
  }

  acrw8_t cnt = 0x05;

  // Write pipline data back to memory
  unsigned long long ret = 0;
  unsigned long long expected_ret = 0;
  ace_nbsync(0);
  ret = ace_vec_accumulate_sram((uintptr_t) 0, cnt);
  for (int i = 0; i < 5; i++) {
    expected_ret += (unsigned long long) data[i];
  }
  if (expected_ret != ret) {
    printf("%llu vs %llu\n", ret, expected_ret);
    exit(1);
  }
}

void test_crc32()
{
  unsigned char Data[4] = {0x01, 0x02, 0x03, 0x04};
  unsigned int Data32 = 0x01020304;
  unsigned int sw_result, hw_result;
  sw_result = crc32_sw(Data);
  hw_result = ace_crc32(Data32);

  if (sw_result != hw_result) {
    exit(1);
  }
}

void test_ace_encode()
{
  // turn on ACE ERROR interrupt
  __asm__ __volatile__("csrr t0, mstatus\n"
                       "ori t0, t0, 0x8\n"
                       "csrw mstatus, t0\n"
                       "csrr t0, mie\n"
                       "li t3, 0x1000000\n"
                       "or t0, t0, t3\n"
                       "csrw mie, t0\n");

  unsigned int encode_input, encode_result;
  encode_input = 5; // <=7
  encode_result = ace_encode(encode_input);
  return;
  // __asm__ __volatile__("wfi");
  // // If ace_interrupt is triggered after the "wfi" instruction, executing two
  // // "nop" instructions can help prevent the program counter from jumping to
  // an
  // // out-of-range address.
  // __asm__ __volatile__("nop");
  // __asm__ __volatile__("nop");
}

unsigned int crc32_sw(unsigned char* data)
{
  // #define QUOTIENT 0x04c11db7
  unsigned int result;
  int i, j;
  unsigned char octet;

  result = 0xffffffff;

  for (i = 0; i < 4; i++) {
    octet = data[i];
    for (j = 0; j < 8; j++) {
      if ((octet >> 7) ^ (result >> 31)) {
        result = (result << 1) ^ 0x04c11db7;
      } else {
        result = (result << 1);
      }
      octet <<= 1;
    }
  }

  return result;
}

void test_ace_multi_4bits()
{
  int a = 1;
  int b = 2;
  int r0, r1, r2, r3, r4, r5, r6;
  r0 = ace_multi_4bits(a++, b++);
  r1 = ace_multi_4bits(a++, b++);
  r2 = ace_multi_4bits(a++, b++);
  r3 = ace_multi_4bits(a++, b++);
  r4 = ace_multi_4bits(a++, b++);
  r5 = ace_multi_4bits(a++, b++);
  r6 = ace_multi_4bits(a, b);
  if (2 != r0 | 6 != r1 | 12 != r2 | 20 != r3 | 30 != r4 | 42 != r5) {
    exit(1);
  }
}

