unsigned int crc32_sw(unsigned char* data)
{
  // #define QUOTIENT 0x04c11db7
  unsigned int result;
  int i, j;
  unsigned char octet;

  result = 0xffffffff;

  for (i = 0; i < 4; i++) {
    octet = data[i];
    for (j = 0; j < 8; j++) {
      if ((octet >> 7) ^ (result >> 31)) {
        result = (result << 1) ^ 0x04c11db7;
      } else {
        result = (result << 1);
      }
      octet <<= 1;
    }
  }

  return result;
}

