#include "hvm_util.h"
#include "core_v5.h"

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MHVM_CFG_SZ_MSK ((1ULL << 8) - 1)

// Simple HVM memory allocator, no free support
void* malloc_hvm(size_t size) {
  static uint64_t current_hvm_offset = 0;
  static uint64_t hvm_bound = 0;

  if (current_hvm_offset == 0) {
    current_hvm_offset = read_csr(NDS_MHVMB);
    uint64_t hvm_cfg = read_csr(NDS_MHVM_CFG);
    uint64_t hvm_sz = hvm_cfg & MHVM_CFG_SZ_MSK;
    hvm_bound = current_hvm_offset + (1 << hvm_sz);
    printf("hvm_base = %llx, hvm_sz = %llx\n", current_hvm_offset, hvm_sz);
  }

  if ((current_hvm_offset + size) > hvm_bound) {
    printf("HVM memory overflow\n");
    exit(1);
  }

  void* ptr = (void*) current_hvm_offset;
  current_hvm_offset += size;
  return ptr;
}

void free_hvm(void* ptr) {
  // No-op for simplicity
}

