void GenSystemCModel::determineCxxPath() {
  // if users have specified the g++, we do not check it
  if (false == m_CxxPath.empty()) {
    m_CurrCxxPath = m_CxxPath;
    return;
  }

  m_CurrCxxPath = cplt::helper::findAbsoluteRootPath(
      "g++", m_CopilotBinParentPath + "/../../../host-tools/");
}

void GenSystemCModel::createFolder() {
  // if SystemC folder does not exist, create a new one
  // if SysmteC folder exists, rename the existing one and then create a new one
  if (true == boost::filesystem::exists(m_OutputFolder)) {
    const auto BackupFolder = m_OutputFolder + "_Backup";
    // check whether BackupFolder exists, if yes, remove it
    if (true == boost::filesystem::exists(BackupFolder)) {
      boost::filesystem::remove_all(BackupFolder);
    }
    // backup existing one by renaming
    std::cerr << "[CRITICAL WARNING] An existing SystemC folder ("
              << m_OutputFolder
              << ") is found, COPILOT would backup the existing one to "
              << BackupFolder << EL;
    boost::filesystem::rename(m_OutputFolder, m_OutputFolder + "_Backup");
  }

