bool chkUserGivenCxx(const std::string &CxxPath, unsigned NeedCxxVer) {
  // check whether given g++ exists
  if (false == boost::filesystem::exists(CxxPath)) {
    std::cerr << "[ERROR] Cannot find g++ at " << CxxPath << "\n";
    return false;
  } else {
    // check whether given g++ can support c++17
    FILE *pF;
    std::string CxxVerChkCommand = "echo \"int main() {return 0;}\" ";
    CxxVerChkCommand += " | " + CxxPath + " -std=\"c++17\" -E -dM -x c++ - ";
    CxxVerChkCommand += " | grep __cplusplus";
    pF = popen(CxxVerChkCommand.c_str(), "r");
    char Buf[100];
    fgets(Buf, sizeof(Buf), pF);
    pclose(pF);
    std::string VerStr{Buf};
    // parse execution result, e.g., #define __cplusplus 201703L, to extract
    // g++ version
    const std::string PatternStr = ".*[[:space:]]+([[:xdigit:]]+)L[[:space:]]*";
    static const std::regex VerRegex(PatternStr);
    std::smatch VerMatch;
    unsigned int CxxVer = 0;
    if (std::regex_match(VerStr, VerMatch, VerRegex)) {
      CxxVer = strtoull(std::string(VerMatch[1]).c_str(), NULL, 10);
    }
    // "201103", for C++11
    // "201402", for C++14
    // "201703", for C++17
    if (17 == NeedCxxVer && CxxVer < 201703) {
      std::cerr << "[ERROR] Given g++ (" << CxxPath
                << ") cannot support C++17\n";
      return false;
    } else if (11 == NeedCxxVer && CxxVer < 201103) {
      std::cerr << "[ERROR] Given g++ (" << CxxPath
                << ") cannot support C++11\n";
      return false;
    }
  }

  return true;
