std::string serialize(const ACE_Core &AceCore, const string &path, bool encrypt) {
  const std::string raw_data = [&]() {
    std::ostringstream oss;
    oss << std::setw(4) << json(AceCore);
    return oss.str();
  }();

  const std::string output_file = [&]() {
    if (encrypt) {
      return path + ".json.enc";
    } else {
      return path + ".json";
    }
  }();

  std::ofstream ofs(output_file, std::ios::binary);

  if (!ofs) {
    cplt::diagnostic::emitError() << "Failed to open file: " << path;
    return {};
  }

  if (encrypt) {
    const auto iv = generate_iv();
    const auto enc_size = plusaes::get_padded_encrypted_size(raw_data.size());
    std::vector<unsigned char> key = plusaes::key_from_string(&ACE_JSON_KEY);
    std::vector<unsigned char> enc_data(enc_size);

    plusaes::encrypt_cbc(reinterpret_cast<const unsigned char*>(raw_data.data()),
                         raw_data.size(), &key[0], key.size(),
                         reinterpret_cast<const unsigned char(*)[16]>(iv.data()),
                         &enc_data[0], enc_data.size(), true);
    ofs.write(reinterpret_cast<const char*>(iv.data()), 16);
    ofs.write(reinterpret_cast<const char*>(enc_data.data()), enc_size);
  } else {
    ofs << raw_data;
  }

  return output_file;
}
} // namespace serde
